//	and applied at activation, not creation. Prefer revokePreviousAfterHours.
//	importKey: The PEM-encoded private key to use for the issuer.
//	importKeyId: The key id to use as the imported key's JWT/JWKS `kid`. Only
//	allowed when `importKey` is provided. Not required to be unique; the
//	addressable key id is the server-minted `keyId` returned in the response.
func CreateKmsSigningKey(ctx context.Context, clientConfig ClientConfig, params CreateKmsSigningKeyParams, opts ...RequestOption) (*CreateKmsSigningKeyResponse, error) {
	issuerId := params.IssuerId
	teamId := params.TeamId
	slug := params.Slug
	activation := params.Activation
	revokePreviousAfterHours := params.RevokePreviousAfterHours
	revokePreviousAt := params.RevokePreviousAt
	importKey := params.ImportKey
	importKeyId := params.ImportKeyId

	if revokePreviousAfterHours != nil {
		if err := ValidateRange("revokePreviousAfterHours", *revokePreviousAfterHours, RangeOpts{Min: Ptr[float64](0)}); err != nil {
			return nil, err
		}
	}

	if importKeyId != nil {
		if err := ValidateLength("importKeyId", *importKeyId, LengthOpts{Max: Ptr[int](128)}); err != nil {
			return nil, err
		}
		if err := ValidatePattern("importKeyId", *importKeyId, "^[A-Za-z0-9._-]+$"); err != nil {
			return nil, err
		}
	}

	resp, err := DoCfg[CreateKmsSigningKeyResponse](ctx, &clientConfig, "POST", fmt.Sprintf("/v1/kms/issuers/%s/keys", EncodePathSegment(issuerId)), &RequestOpts{
		Query: map[string]any{
			"teamId": QueryValue{Value: teamId, Style: "form", Explode: true},
			"slug":   QueryValue{Value: slug, Style: "form", Explode: true},
		},
		Body: map[string]any{
			"activation":               activation,
			"revokePreviousAfterHours": revokePreviousAfterHours,
			"revokePreviousAt":         revokePreviousAt,
			"importKey":                importKey,
			"importKeyId":              importKeyId,
		},
		OperationID: "CreateKmsSigningKey",
		Options:     opts,
	})
	if err != nil {
		return nil, err
	}
	return &resp.Data, nil
}

